begin;
grant usage on schema public to authenticated,service_role;
create table public.vsv_access(user_id uuid primary key references auth.users(id), email text not null default '', technical_admin boolean not null default false, active boolean not null default true, updated_at timestamptz not null default now());
alter table public.vsv_access enable row level security;
create function public.vsv_active() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.vsv_access where user_id=auth.uid() and active)$$;
create function public.vsv_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.vsv_access where user_id=auth.uid() and active and technical_admin)$$;
revoke all on function public.vsv_active(),public.vsv_admin() from public;
grant execute on function public.vsv_active(),public.vsv_admin() to authenticated;
grant select on public.vsv_access to authenticated;
create policy own_access on public.vsv_access for select to authenticated using(user_id=auth.uid() or public.vsv_admin());
create table public.vsv_documents(kind text not null check(kind in ('projects','meetings','pvs','reviews')),id text not null check(length(id) between 1 and 200),payload jsonb,version bigint not null default 1,deleted boolean not null default false,updated_at timestamptz not null default now(),updated_by uuid references auth.users(id),ordinal bigint generated by default as identity,primary key(kind,id),check(deleted or payload is not null and jsonb_typeof(payload)='object'));
create table public.vsv_references(like public.vsv_documents including defaults including constraints including indexes including identity);
alter table public.vsv_references drop constraint vsv_documents_kind_check;
alter table public.vsv_references add check(kind in ('members','articles','places','suppliers','articleCategories','placeCategories'));
create table public.vsv_operations(like public.vsv_documents including defaults including constraints including indexes including identity);
alter table public.vsv_operations drop constraint vsv_documents_kind_check;
alter table public.vsv_operations add check(kind in ('movements','reservations','reservationEvents','loans','receipts','sessions','sales','refunds','cashMoves','shoppingNeeds','purchases','modeChanges','paymentTransfers','heldOrders','purchaseOrders','baskets'));
create table public.vsv_settings(like public.vsv_documents including defaults including constraints including indexes including identity);
alter table public.vsv_settings drop constraint vsv_documents_kind_check;
alter table public.vsv_settings add check(kind in ('common','meta'));
create table public.vsv_clock(id boolean primary key default true check(id),revision bigint not null default 0);
insert into public.vsv_clock default values;
create table public.vsv_requests(id uuid primary key,actor uuid not null references auth.users(id),fingerprint text not null,result jsonb,created_at timestamptz not null default now());
create table public.vsv_migrations(id text primary key,actor uuid not null references auth.users(id),report jsonb not null,created_at timestamptz not null default now());
create table public.vsv_invites(email text primary key,actor uuid not null references auth.users(id),state text not null check(state in ('pending','sent','failed')),updated_at timestamptz not null default now());
create table public.vsv_files(id text primary key,path text not null unique,name text not null,mime text not null,size integer not null check(size between 1 and 5242880),created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
do $$declare t text;begin foreach t in array array['vsv_documents','vsv_references','vsv_operations','vsv_settings','vsv_clock','vsv_requests','vsv_migrations','vsv_invites','vsv_files'] loop execute format('alter table public.%I enable row level security',t);execute format('grant select on public.%I to authenticated',t);execute format('create policy active_read on public.%I for select to authenticated using(public.vsv_active())',t);end loop;end$$;
drop policy active_read on public.vsv_requests;
create policy request_owner on public.vsv_requests for select to authenticated using(public.vsv_active() and (actor=auth.uid() or public.vsv_admin()));
drop policy active_read on public.vsv_migrations;
create policy migration_admin on public.vsv_migrations for select to authenticated using(public.vsv_admin());
drop policy active_read on public.vsv_invites;
create policy invite_admin on public.vsv_invites for select to authenticated using(public.vsv_admin());
-- Aucune écriture associative directe, même pour un administrateur connecté.
revoke all on public.vsv_access,public.vsv_documents,public.vsv_references,public.vsv_operations,public.vsv_settings,public.vsv_clock,public.vsv_requests,public.vsv_migrations,public.vsv_invites,public.vsv_files from anon;
grant all on public.vsv_access,public.vsv_documents,public.vsv_references,public.vsv_operations,public.vsv_settings,public.vsv_clock,public.vsv_requests,public.vsv_migrations,public.vsv_invites,public.vsv_files to service_role;
create function public.vsv_assert_actor(p_actor uuid,p_admin boolean default false) returns void language plpgsql security definer set search_path='' as $$begin perform 1 from public.vsv_access where user_id=p_actor and active and (not p_admin or technical_admin) for share;if not found then raise exception 'Accès VSV refusé' using errcode='42501';end if;end$$;
create function public.vsv_snapshot(p_actor uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare rows jsonb;rev bigint;begin select revision into rev from public.vsv_clock where id for share;perform public.vsv_assert_actor(p_actor);select coalesce(jsonb_agg(x order by x."table",x.kind,x.ordinal),'[]') into rows from (select 'vsv_documents' as "table",kind,id,payload,version,deleted,ordinal from public.vsv_documents union all select 'vsv_references',kind,id,payload,version,deleted,ordinal from public.vsv_references union all select 'vsv_operations',kind,id,payload,version,deleted,ordinal from public.vsv_operations union all select 'vsv_settings',kind,id,payload,version,deleted,ordinal from public.vsv_settings)x;return jsonb_build_object('rows',rows,'revision',rev);end$$;
-- Le verrou sérialise la validation de la révision et TOUTES les écritures d’une opération.
create function public.vsv_commit(p_actor uuid,p_id uuid,p_fingerprint text,p_revision bigint,p_changes jsonb,p_result jsonb,p_migration text default null) returns jsonb language plpgsql security definer set search_path='' as $$declare c jsonb;v bigint;rev bigint;old public.vsv_requests;begin
 select revision into rev from public.vsv_clock where id for update;
 perform public.vsv_assert_actor(p_actor,p_migration is not null);
 select * into old from public.vsv_requests where id=p_id;
 if found then if old.actor<>p_actor or old.fingerprint<>p_fingerprint then raise exception 'Identifiant de requête déjà utilisé' using errcode='23505';end if;return jsonb_build_object('result',old.result,'duplicate',true);end if;
 if rev<>p_revision then raise exception 'RETRY_REVISION' using errcode='40001';end if;
 if jsonb_typeof(p_changes)<>'array' or jsonb_array_length(p_changes)>10000 then raise exception 'Modifications invalides';end if;
 for c in select value from jsonb_array_elements(p_changes) loop
 if c->>'table' not in ('vsv_documents','vsv_references','vsv_operations','vsv_settings') then raise exception 'Table interdite';end if;
 execute format('select version from public.%I where kind=$1 and id=$2',c->>'table') into v using c->>'kind',c->>'id';
 if coalesce(v,0)<>(c->>'expected')::bigint then raise exception 'CONFLICT' using errcode='40001';end if;
 execute format('insert into public.%I(kind,id,payload,version,deleted,updated_by) values($1,$2,$3,$4,$5,$6) on conflict(kind,id) do update set payload=excluded.payload,version=excluded.version,deleted=excluded.deleted,updated_by=excluded.updated_by,updated_at=now()',c->>'table') using c->>'kind',c->>'id',c->'payload',coalesce(v,0)+1,(c->>'deleted')::boolean,p_actor;
 end loop;
 insert into public.vsv_requests(id,actor,fingerprint,result)values(p_id,p_actor,p_fingerprint,p_result);
 if p_migration is not null then insert into public.vsv_migrations(id,actor,report) values(p_migration,p_actor,p_result) on conflict(id) do nothing;end if;
 update public.vsv_clock set revision=revision+1 where id;return jsonb_build_object('result',p_result,'duplicate',false);
end$$;
create function public.vsv_set_access(p_actor uuid,p_target uuid,p_active boolean) returns void language plpgsql security definer set search_path='' as $$begin perform 1 from public.vsv_clock where id for update;perform public.vsv_assert_actor(p_actor,true);lock table public.vsv_access in share row exclusive mode;if not p_active and exists(select 1 from public.vsv_access where user_id=p_target and technical_admin and active) and (select count(*) from public.vsv_access where technical_admin and active)<2 then raise exception 'Conservez au moins un administrateur actif';end if;update public.vsv_access set active=p_active,updated_at=now() where user_id=p_target;if not found then raise exception 'Compte introuvable';end if;end$$;
create function public.vsv_claim_invite(p_actor uuid,p_email text) returns boolean language plpgsql security definer set search_path='' as $$begin perform public.vsv_assert_actor(p_actor,true);insert into public.vsv_invites(email,actor,state)values(lower(trim(p_email)),p_actor,'pending') on conflict(email)do update set state='pending',actor=p_actor,updated_at=now() where vsv_invites.state='failed' and vsv_invites.updated_at<now()-interval '1 minute';return found;end$$;
-- Toutes les RPC à paramètre actor sont exclusivement réservées au serveur.
do $$declare f record;begin for f in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('vsv_assert_actor','vsv_snapshot','vsv_commit','vsv_set_access','vsv_claim_invite') loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end$$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('vsv-private','vsv-private',false,5242880,array['image/jpeg','image/png','image/webp','application/pdf']) on conflict(id)do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy vsv_file_read on storage.objects for select to authenticated using(bucket_id='vsv-private' and public.vsv_active());
-- Ces politiques restrictives protègent aussi ce bucket contre une ancienne politique trop large.
grant execute on function public.vsv_active() to anon;
create policy vsv_private_read_guard on storage.objects as restrictive for select to anon,authenticated using(bucket_id<>'vsv-private' or public.vsv_active());
create policy vsv_private_insert_guard on storage.objects as restrictive for insert to anon,authenticated with check(bucket_id<>'vsv-private');
create policy vsv_private_update_guard on storage.objects as restrictive for update to anon,authenticated using(bucket_id<>'vsv-private') with check(bucket_id<>'vsv-private');
create policy vsv_private_delete_guard on storage.objects as restrictive for delete to anon,authenticated using(bucket_id<>'vsv-private');
-- Téléversement, modification et suppression uniquement par l’Edge Function (formats vérifiés).
do $$declare t text;begin foreach t in array array['vsv_clock','vsv_access'] loop if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename=t)then execute format('alter publication supabase_realtime add table public.%I',t);end if;end loop;end$$;
notify pgrst, 'reload schema';
commit;
